export class BaseRecognitionService{options;debugging;session;platform;engine;constructor(platform,session,options={},debugging={},engine="opencv"){this.platform=platform;this.session=session;this.options={...DEFAULT_RECOGNITION_OPTIONS,...options};this.debugging={...DEFAULT_DEBUGGING_OPTIONS,...debugging};if(engine==="opencv"&&!this.platform.imageProcessor){this.engine="canvas-native"}else{this.engine=engine}}log(message){if(this.debugging.verbose){console.log(`[RecognitionService] ${message}`)}}async run(image,detection,charactersDictionary,strategy="per-line",perCallOptions){this.log("Starting text recognition process");try{let sourceCanvasForCrop;if(this.platform.isCanvas(image)){sourceCanvasForCrop=image}else if(this.engine==="opencv"&&this.platform.imageProcessor){sourceCanvasForCrop=await this.platform.imageProcessor.prepareCanvas(image)}else{sourceCanvasForCrop=await this.platform.canvas.prepareCanvas(image)}let validBoxes=this.filterValidBoxes(detection);if(validBoxes.length===0){return[]}const{canvas:cropCanvas,ratio:cropRatio}=this.buildCropCanvas(sourceCanvasForCrop);let cropBoxes=cropRatio===1?validBoxes:validBoxes.map((v)=>({...v,box:scaleBox(v.box,cropRatio)}));let ctx=this.buildContext(perCallOptions);let results;switch(strategy){case"cross-line":results=await runCrossLineStrategy(cropCanvas,cropBoxes,ctx,charactersDictionary);break;case"per-line":results=await runLineStrategy(cropCanvas,cropBoxes,ctx,charactersDictionary);break;case"per-box":default:results=await runPerBoxStrategy(cropCanvas,cropBoxes,ctx,(canvas,box,index,total,debugPath,dict)=>this.processBox(canvas,box,index,total,debugPath,ctx,dict),charactersDictionary)}if(cropRatio!==1){results=results.map((r)=>({...r,box:scaleBox(r.box,1/cropRatio)}))}let minimumConfidence=perCallOptions?.minimumConfidence??this.options.minimumConfidence??DEFAULT_RECOGNITION_OPTIONS.minimumConfidence??DISABLED_CONFIDENCE_THRESHOLD;return minimumConfidence>DISABLED_CONFIDENCE_THRESHOLD?results.filter((r)=>{let bar=/[\p{L}\p{N}]/u.test(r.text)?minimumConfidence:Math.min(MAXIMUM_CONFIDENCE,minimumConfidence+SYMBOL_CONFIDENCE_OFFSET);return r.confidence>=bar}):results}catch(error){console.error("Error during text recognition:",error instanceof Error?error.message:String(error));return[]}}buildContext(perCallOptions){let options={...this.options,...perCallOptions?.spaceRecovery!==undefined?{spaceRecovery:perCallOptions.spaceRecovery}:{},...perCallOptions?.rotateVerticalCrops!==undefined?{rotateVerticalCrops:perCallOptions.rotateVerticalCrops}:{},...perCallOptions?.recBatchSize!==undefined?{recBatchSize:perCallOptions.recBatchSize}:{}};return{platform:this.platform,options:supportsDynamicBatch(this.session)?options:{...options,recBatchSize:SEQUENTIAL_BATCH_SIZE},debugging:this.debugging,engine:this.engine,runInference:(t)=>this.runInference(t)}}filterValidBoxes(boxes){return boxes.map((box,index)=>({box,index})).filter(({box,index})=>this.isValidBox(box,index))}buildCropCanvas(source){const{width,height}=source;let maxCropSourceSideLength=this.options.maxCropSourceSideLength??2000;const{width:resizeW,height:resizeH,ratio}=calculateResizeDimensions(width,height,maxCropSourceSideLength);if(ratio===1){return{canvas:source,ratio:1}}let resized=this.platform.createCanvas(resizeW,resizeH);resized.getContext("2d").drawImage(source,0,0,width,height,0,0,resizeW,resizeH);return{canvas:resized,ratio}}async processBox(sourceCanvas,box,index,totalBoxes,debugPath,ctx,charactersDictionary){let start=Date.now();try{let cropCanvas=rotateTallCropIfNeeded(cropRegion(sourceCanvas,box,this.platform.canvas),ctx);const[recognized]=await recognizeCropsBatched([cropCanvas],ctx,charactersDictionary);let recognizedText=recognized?.text??"";let confidence=recognized?.confidence??0;if(this.debugging.debug&&debugPath){await this.platform.saveDebugImage(cropCanvas,`crop_${String(index).padStart(3,"0")}.png`,debugPath);let processingTime=Date.now()-start;this.log(`Box ${index+1}/${totalBoxes}: [x:${box.x}, y:${box.y}, w:${box.width}, h:${box.height}]`+`
	 -> "${recognizedText}" (processed in ${processingTime}ms)
`)}return{text:recognizedText,box,confidence}}catch(e){let err=e instanceof Error?e:new Error(String(e));console.error(`Error processing box ${index+1}: ${err.message}`,err.stack);return null}}isValidBox(box,index){if(box.width<=0||box.height<=0){console.warn(`Skipping invalid box ${index+1}: w=${box.width}, h=${box.height}`);return false}return true}async runInference(inputTensor){let yieldMs=this.options.mainThreadYieldMs??0;if(yieldMs>0){await new Promise((resolve)=>setTimeout(resolve,yieldMs))}let feeds={x:inputTensor};let results=await this.session.run(feeds);let outputNodeName=Object.keys(results)[0];let outputTensor=outputNodeName?results[outputNodeName]:undefined;if(!outputTensor){throw new Error(`Recognition output tensor '${outputNodeName}' not found. Available keys: ${Object.keys(results)}`)}return outputTensor}}import{DEFAULT_DEBUGGING_OPTIONS,DEFAULT_RECOGNITION_OPTIONS}from"../constants.js";import{calculateResizeDimensions}from"./detection/box-geometry.js";import{recognizeCropsBatched,supportsDynamicBatch}from"./recognition/batched.js";import{cropRegion,rotateTallCropIfNeeded,runCrossLineStrategy,runLineStrategy,runPerBoxStrategy}from"./recognition/strategies.js";let DISABLED_CONFIDENCE_THRESHOLD=0;let MAXIMUM_CONFIDENCE=1;let SEQUENTIAL_BATCH_SIZE=1;let SYMBOL_CONFIDENCE_OFFSET=0.3;function scaleBox(box,ratio){return{x:Math.round(box.x*ratio),y:Math.round(box.y*ratio),width:Math.max(1,Math.round(box.width*ratio)),height:Math.max(1,Math.round(box.height*ratio))}}